<?php require __DIR__.'/auth.php'; require_login(); page_start('Ghi chú','note'); ?><main class="page"><div class="hero"><div><div class="eyebrow">Ghi chú cá nhân</div><h1>Góc ghi chú</h1><p>Mỗi ghi chú được lưu riêng cho tài khoản của bạn.</p></div><button class="button" id="new">+ Ghi chú mới</button></div><div class="notes-layout"><aside class="card note-list" id="noteList"><div class="empty">Đang tải...</div></aside><section class="card note-box"><input id="title" class="note-title" placeholder="Tiêu đề ghi chú"><textarea id="content" maxlength="10000" placeholder="Bắt đầu viết ghi chú của bạn..."></textarea><div class="note-actions"><span class="status" id="status">Chọn một ghi chú hoặc tạo mới</span><button class="button" id="save">Lưu ghi chú</button></div></section></div></main><script>const list=document.querySelector('#noteList'),title=document.querySelector('#title'),content=document.querySelector('#content'),status=document.querySelector('#status');let notes=[],current=0;const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));function load(){fetch('notes.php').then(r=>r.json()).then(x=>{notes=x;list.innerHTML=x.length?x.map(n=>`<button class="note-item ${n.id===current?'selected':''}" data-id="${n.id}"><strong>${esc(n.title)}</strong><small>${esc(n.updated_at)}</small><span>${esc(n.preview)}</span></button>`).join(''):'<div class="empty">Chưa có ghi chú</div>';document.querySelectorAll('.note-item').forEach(b=>b.onclick=()=>openNote(b.dataset.id))}).catch(()=>list.innerHTML='<div class="empty">Không tải được ghi chú</div>')}function openNote(id){fetch('notes.php?id='+id).then(r=>r.json()).then(n=>{current=n.id;title.value=n.title;content.value=n.content;status.textContent='Cập nhật: '+n.updated_at;load()})}document.querySelector('#new').onclick=()=>{current=0;title.value='';content.value='';title.focus();status.textContent='Ghi chú mới'};document.querySelector('#save').onclick=()=>{status.textContent='Đang lưu...';fetch('notes.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:current,title:title.value,content:content.value})}).then(r=>r.json()).then(x=>{if(x.ok){current=x.id;status.textContent='Đã lưu thành công';load()}else status.textContent=x.error||'Lưu thất bại'})};load();</script><?php page_end(); ?>